(() => {
  const section = document.getElementById('UgcVideoCarousel-template--19937133822054__ugc_video_carousel_x7dpi6');

  if (!section || section.dataset.ugcCarouselInitialized === 'true') return;
  section.dataset.ugcCarouselInitialized = 'true';

  const track = section.querySelector('[data-track]');
  const cards = Array.from(section.querySelectorAll('[data-card]'));
  const prevButton = section.querySelector('[data-prev]');
  const nextButton = section.querySelector('[data-next]');
  let scrollFrame = null;

  if (track && cards.length) {
    const setActiveCard = () => {
      const center = track.scrollLeft + track.clientWidth / 2;
      let activeCard = cards[0];
      let minDistance = Infinity;

      cards.forEach((card) => {
        const cardCenter = card.offsetLeft + card.offsetWidth / 2;
        const distance = Math.abs(center - cardCenter);

        if (distance < minDistance) {
          minDistance = distance;
          activeCard = card;
        }
      });

      cards.forEach((card) => card.classList.toggle('is-active', card === activeCard));
    };

    const scrollToCard = (direction) => {
      const activeIndex = Math.max(
        cards.findIndex((card) => card.classList.contains('is-active')),
        0
      );
      const targetIndex = Math.min(Math.max(activeIndex + direction, 0), cards.length - 1);
      const targetCard = cards[targetIndex];

      if (!targetCard) return;

      const targetLeft = targetCard.offsetLeft - (track.clientWidth - targetCard.offsetWidth) / 2;
      track.scrollTo({ left: Math.max(targetLeft, 0), behavior: 'smooth' });
    };

    prevButton?.addEventListener('click', () => scrollToCard(-1));
    nextButton?.addEventListener('click', () => scrollToCard(1));

    track.addEventListener('scroll', () => {
      if (scrollFrame) cancelAnimationFrame(scrollFrame);
      scrollFrame = requestAnimationFrame(setActiveCard);
    });

    window.addEventListener('resize', setActiveCard);
    setActiveCard();
  }

  const closeDialog = (dialog) => {
    const container = dialog.querySelector('[data-dialog-content]');
    if (container) container.innerHTML = '';
    if (dialog.open) dialog.close();
  };

  section.querySelectorAll('[data-open-modal]').forEach((trigger) => {
    trigger.addEventListener('click', () => {
      const dialogId = trigger.getAttribute('data-open-modal');
      const dialog = dialogId ? document.getElementById(dialogId) : null;

      if (!dialog) return;

      const container = dialog.querySelector('[data-dialog-content]');
      const template = dialog.querySelector('template');

      if (container && template) container.innerHTML = template.innerHTML;
      if (typeof dialog.showModal === 'function') dialog.showModal();
    });
  });

  section.querySelectorAll('[data-dialog]').forEach((dialog) => {
    dialog.addEventListener('click', (event) => {
      if (event.target === dialog || event.target.closest('[data-close]')) {
        closeDialog(dialog);
      }
    });

    dialog.addEventListener('close', () => {
      const container = dialog.querySelector('[data-dialog-content]');
      if (container) container.innerHTML = '';
    });
  });
})();
